// Emitters for the generated Lean files under lean/BoltProof/Bridge/Generated/.
//
// Everything is emitted as hex `String` literals (never `List Nat` literals): bsv-script-lean decodes
// them at evaluation time, which keeps elaboration fast and the generated files diffable.

export type Expect = 'valid' | 'anyInvalid' | 'skip' | { invalid: string }

export interface Prevout { script: string; satoshis: number }

export interface Vec {
  name: string
  family: string
  txHex: string
  prevouts: Prevout[]
  expect: Expect[]
  note: string
}

export interface SuffixEntry { ident: string; suffixHex: string; fingerprintHex: string; type: string }

const HEADER = `-- GENERATED by \`npm run lean:vectors\` (lean/vectors/export.test.ts). Do not hand-edit.
-- Regenerate after any change to a covenant template, a test helper, or the pinned expectations.
`

const leanString = (s: string): string => `"${s.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`

const expectTerm = (e: Expect): string =>
  e === 'valid' ? '.valid' : e === 'anyInvalid' ? '.anyInvalid' : e === 'skip' ? '.skip' : `.invalid ${leanString(e.invalid)}`

/** One `def <name> : Vec := { ... }` per vector, plus `allVectors`. */
export function emitVectors(vecs: Vec[]): string {
  const defs = vecs.map((v) => {
    const prevouts = v.prevouts.map((p) => `{ script := ${leanString(p.script)}, satoshis := ${p.satoshis} }`)
    return `/-- ${v.note.replace(/-\//g, '- /')} -/
def ${v.name} : Vec :=
  { name := ${leanString(v.name)}
    family := ${leanString(v.family)}
    txHex := ${leanString(v.txHex)}
    prevouts := [
      ${prevouts.join(',\n      ')}]
    expect := [${v.expect.map(expectTerm).join(', ')}]
    note := ${leanString(v.note)} }
`
  })
  return `${HEADER}import BoltProof.Bridge.Params

namespace BoltProof.Bridge.Generated

open BoltProof.Bridge

${defs.join('\n')}
/-- Every exported vector, in export order. -/
def allVectors : List Vec := [
  ${vecs.map((v) => v.name).join(',\n  ')}]

end BoltProof.Bridge.Generated
`
}

/** One \`native_decide\` theorem per vector: every input meets its expectation under \`params\`. */
export function emitTheorems(vecs: Vec[]): string {
  const thms = vecs.map((v) => `/-- ${v.note.replace(/-\//g, '- /')} -/
theorem check_${v.name} : ${v.name}.check params = true := by native_decide
`)
  return `${HEADER}import BoltProof.Bridge.Generated.Vectors

/-!
Kernel-registered verdicts of the shipped covenant bytes on real transactions. Each theorem
evaluates bsv-script-lean's \`verifyScript\` on every input of one transaction (through
\`native_decide\`, i.e. \`Lean.ofReduceBool\`) and asserts the verdict the vector expects.
-/

namespace BoltProof.Bridge.Generated

open BoltProof.Bridge

${thms.join('\n')}
end BoltProof.Bridge.Generated
`
}

/** The static covenant suffixes and their REGISTRY fingerprints. */
export function emitBytes(entries: SuffixEntry[]): string {
  const defs = entries.map((e) => `/-- \`${e.type}\`: the compiled locking-script suffix after the data pushes (${e.suffixHex.length / 2} bytes). -/
def ${e.ident}SuffixHex : String :=
  ${leanString(e.suffixHex)}

/-- \`REGISTRY.${e.type}.suffixHashHex\`: the scanner's SHA-256 fingerprint of that suffix. -/
def ${e.ident}FingerprintHex : String := ${leanString(e.fingerprintHex)}
`)
  return `${HEADER}
namespace BoltProof.Bridge.Generated

${defs.join('\n')}
end BoltProof.Bridge.Generated
`
}
